__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"TRAVEL_STAND",{enumerable:!0,get:function(){return t}}),Object.defineProperty(e,"TRAVEL_INTRO",{enumerable:!0,get:function(){return s}}),Object.defineProperty(e,"TRAVEL_GROUPS",{enumerable:!0,get:function(){return l}});const n='https://www.auswaertiges-amt.de/de/service/laender/marokko-node/marokkosicherheit-224080',t='Stand 09.11.2026',s='Kurze Hinweise f\xfcr die Reise, gepr\xfcft am 09.11.2026. Amtliche Quelle ist das Ausw\xe4rtige Amt, die Links stehen jeweils dabei. [\u2026] hei\xdft: nicht belegt. Rechtliche und medizinische Punkte sind keine Beratung, frag im Zweifel Arzt, Vermieter oder Botschaft.',l=[{id:'entry',title:'Einreise (deutscher Pass, Annahme)',icon:'passport',items:['Nur Reisepass, vorl\xe4ufiger Reisepass oder Kinderreisepass. Der Personalausweis reicht nicht.','Der Pass muss bei Einreise noch mindestens 6 Monate g\xfcltig und unbesch\xe4digt sein.','Visumfrei bis 90 Tage f\xfcr Touristen.','Ein Einreiseformular nennt das Ausw\xe4rtige Amt nicht. Ob es aktuell eines gibt: [\u2026]','Passkopie (Farbe) und Foto des Passes dabeihaben, den Pass selbst nie als Pfand hinterlegen.','Meiden: Westsahara und die Grenzregion zu Algerien (dringend abgeraten).'],links:[{label:'Ausw\xe4rtiges Amt: Marokko',url:n}]},{id:'elefand',title:'ELEFAND',icon:'account-alert-outline',items:['Krisenvorsorgeliste des Ausw\xe4rtigen Amts. Das Amt empfiehlt allen Deutschen den Eintrag, vor der Reise machen.','Deutsche Botschaft Rabat, Konsularabteilung: +212 537 63 54 00. Honorarkonsul Agadir: +212 528 84 10 25. AA-Notruf: +49 30 18 17 2000.'],links:[{label:'ELEFAND eintragen',url:'https://krisenvorsorgeliste.diplo.de/signin'},{label:'Deutsche Botschaft Rabat',url:'https://rabat.diplo.de/ma-de'}]},{id:'phone',title:'Handy',icon:'cellphone',items:['Marokko liegt au\xdferhalb des EU-Roamings. Bei der Telekom bleibt Datenverkehr au\xdferhalb der EU gesperrt, bis ein Datenpass gebucht ist (ab 5,95 \u20ac). Preise f\xfcr Marokko und f\xfcr andere Anbieter: [\u2026]','Alternativ lokale eSIM oder SIM (Orange, inwi, Maroc Telecom). Anbieter verlangen eine Identifikation mit Ausweisdokument. Ob das am Flughafen Agadir geht: [\u2026]','Karten der Strecke vorher offline laden.'],links:[{label:'Telekom: Roaming',url:'https://www.telekom.de/unterwegs/tarife-und-optionen/roaming'},{label:'Orange: eSIM',url:'https://www.orange.ma/Offres-services/Offres-Mobile/eSIM'},{label:'inwi: eSIM',url:'https://www.inwi.ma/esim'}]},{id:'carry',title:'Dabeihaben',icon:'bag-personal-outline',items:['Dokumente: Pass und Farbkopie, F\xfchrerschein (ggf. internationaler), Mietvertrag, gr\xfcne Versicherungskarte, Versicherungsnachweis, Impfpass.','Geld: Kreditkarte mit freiem Limit f\xfcr die Kaution, etwas Euro zum Tausch. Dirham darf man nur bis 2.000 MAD ein- und ausf\xfchren. Tausch nur in Banken oder zugelassenen Wechselstuben, Belege aufbewahren. Kurs 01.11.: 1 \u20ac \u2248 10,98 MAD.','Karte wird weit akzeptiert, auf M\xe4rkten und in kleinen Lokalen oft nur Bargeld. Girocard vorher auf Auslandseinsatz pr\xfcfen.','Keine Drohne mitnehmen: Einfuhr streng verboten, der Zoll beschlagnahmt sie.','Versicherung: Auslandskranken mit R\xfccktransport. Kliniken k\xf6nnen die Ausreise verweigern, bis bezahlt ist.'],links:[{label:'Ausw\xe4rtiges Amt: Marokko',url:n},{label:'ADAC: Einreise und Zoll',url:'https://www.adac.de/reise-freizeit/reiseplanung/reiseziele/marokko/uebersicht/einreise-zoll/'}]},{id:'pharmacy',title:'Reiseapotheke und Gesundheit',icon:'medical-bag',items:['Pflichtimpfungen gibt es bei Einreise aus Deutschland keine. Das Ausw\xe4rtige Amt empfiehlt Hepatitis A und die Standardimpfungen nach STIKO (besonders Masern, Diphtherie). Tollwut, Hepatitis B und Typhus nach individueller Indikation. Beratung beim Arzt.','Tollwut: Impfstoff und Immunglobuline gibt es im Land kaum. Streunende Hunde meiden. Nach Biss oder Kratzer Wunde mit Seife und Wasser sp\xfclen und sofort zum Arzt.','Trinkwasser: Das Tropeninstitut r\xe4t zu Flaschenwasser oder abgekochtem Wasser. Eine eigene Aussage zum Leitungswasser: [\u2026]','Einpacken: Durchfallmittel, Sonnenschutz (starke UV-Strahlung), Wundversorgung f\xfcr Surfwunden, eigene Medikamente mit \xe4rztlicher Liste auf Englisch.','Auf dem Land ist die Notfallversorgung eingeschr\xe4nkt. Zur Versorgung in Agadir und Taghazout: [\u2026]'],links:[{label:'Tropeninstitut: Marokko',url:'https://tropeninstitut.de/ihr-reiseziel/marokko'},{label:'Notrufnummern (Tropeninstitut)',url:'https://tropeninstitut.de/reisetipps/tipps-waehrend-der-reise/notrufnummern'}]},{id:'rental',title:'Mietwagen-\xdcbergabe',icon:'car-key',items:['Der deutsche F\xfchrerschein gilt laut Ausw\xe4rtigem Amt bis zu ein Jahr. Der ADAC nennt den internationalen F\xfchrerschein empfohlen, Vermieter k\xf6nnen ihn verlangen. Vorher beim Vermieter nachfragen.','Kreditkarte auf den Namen des Fahrers mit genug Limit f\xfcr die Kaution. H\xf6he: [\u2026]','Fotos und Video von allen Seiten, Felgen, Scheiben und Innenraum. Tankstand schriftlich festhalten.','Selbstbeteiligung kl\xe4ren und was ausgeschlossen ist: oft Reifen, Felgen, Unterboden, Schl\xfcssel, Innenraum, nicht eingetragene Fahrer. M\xf6glichst Vollkasko.','Bei Unfall oder Diebstahl sofort Polizeibericht verlangen, sonst kann die Deckung entfallen.','Dachtr\xe4ger oder Boardtransport vorher mit dem Vermieter kl\xe4ren.','Typische Abzock-Maschen: [\u2026] nicht belegt.'],links:[{label:'ADAC: Fahrzeug und Papiere',url:'https://www.adac.de/reise-freizeit/reiseplanung/reiseziele/marokko/fahrzeug/'},{label:'Marhire: Mietwagen-Versicherung (Anbieter)',url:'https://marhire.com/en/article/morocco-car-rental-insurance-explained'}]},{id:'drive',title:'Fahren',icon:'steering',items:['Flughafen Agadir bis Imsouane: Fahrzeit [\u2026]. Eigene Sch\xe4tzung (Annahme): etwa 1,5 bis 2 Stunden \xfcber die K\xfcstenstra\xdfe.','Nachts nicht fahren, wenn es vermeidbar ist: unbeleuchtete Fahrzeuge, Tiere und Fu\xdfg\xe4nger auf der Stra\xdfe, teils schlechte Stra\xdfen. Im November wird es fr\xfch dunkel, plane die Ankunft davor.','Tempolimits (ADAC, Pkw): innerorts 40 (je nach Schild bis 60), au\xdferorts 100, Autobahn 120. Promille 0,0. Telefonieren nur mit Freisprecheinrichtung.','Kontrollen: langsam heranfahren, nur auf Zeichen anhalten. F\xfchrerschein, Passkopie und Mietpapiere griffbereit. Blitzer h\xe4ufig an Ortseinfahrten und nach Kreisverkehren (Erfahrungswerte). Bu\xdfgeldh\xf6hen: [\u2026]','Kreisverkehr: laut ADAC rechts vor links, sofern nicht beschildert. Auf Schilder achten.','Tanken: Benzin ca. 1,40 \u20ac/l, Diesel ca. 1,52 \u20ac/l (06.11.). Gelegentlich Engp\xe4sse, in Agadir voll tanken.','Parken am Spot: Parkw\xe4chter und Trinkgeld [\u2026]. Parkverbot bei rot-wei\xdfen Bordsteinstreifen.'],links:[{label:'ADAC: Fahrzeug und Papiere',url:'https://www.adac.de/reise-freizeit/reiseplanung/reiseziele/marokko/fahrzeug/'}]},{id:'respect',title:'Respekt und Verhalten',icon:'hand-heart-outline',items:['Die Gesellschaft ist \xfcberwiegend konservativ. Z\xe4rtlichkeiten in der \xd6ffentlichkeit vermeiden (Ausw\xe4rtiges Amt).','Kleidung: Abseits vom Strand Schultern und Knie bedecken, auf dem Land strenger als in Touristenorten (Reisef\xfchrer, nicht amtlich).','Fotos von Menschen nur nach Fragen, besonders bei Frauen. Drohnen sind verboten (Ausw\xe4rtiges Amt).','Mit der rechten Hand essen, gr\xfc\xdfen und bezahlen, die linke gilt als unrein (Reisef\xfchrer, nicht amtlich).','Moscheen sind f\xfcr Nicht-Muslime meist nicht zug\xe4nglich. Ausnahme: gef\xfchrte Touren in der Hassan-II.-Moschee in Casablanca (Reisef\xfchrer, nicht amtlich).','Handeln auf dem Markt ist \xfcblich und freundlich gemeint. Wer einem Preis zustimmt, kauft auch. Bei \u201ePrix fixe" wird nicht gehandelt (Reisef\xfchrer, nicht amtlich).','Ein \u201eSalam alaikum" zur Begr\xfc\xdfung und \u201eShukran" (danke) \xf6ffnen T\xfcren. Meine Empfehlung, keine Quelle.'],links:[{label:'Ausw\xe4rtiges Amt: Marokko',url:n},{label:"Frommer's: Etikette in Marokko (englisch)",url:'https://www.frommers.com/destinations/morocco/etiquette'}]},{id:'money',title:'Bargeld und Trinkgeld',icon:'cash-multiple',items:['W\xe4hrung ist der Dirham (MAD). Ein- und Ausfuhr h\xf6chstens 2.000 MAD in bar, Devisen ab umgerechnet 100.000 MAD anmelden (Ausw\xe4rtiges Amt).','Kurs etwa 11 MAD f\xfcr 1 Euro (Referenzkurs Bank Al-Maghrib, Anfang November 2026, laut Presse).','Imsouane: kein Geldautomat gefunden, nur eine Wechselstube [nicht belegt]. Bargeld vorher holen.','Taghazout: Angaben zu Geldautomaten widerspr\xfcchlich, laut einer Quelle ist der n\xe4chste in Aourir [nicht belegt]. In Agadir gibt es viele. Viele Caf\xe9s und kleine L\xe4den nehmen nur bar.','Abhebung meist 2.000 bis 3.000 MAD pro Vorgang, Geb\xfchr bis etwa 35 MAD (Regionalportal, nicht amtlich).','Trinkgeld als Richtwert (Reiseblogs, Angaben schwanken): Caf\xe9 2 bis 10 MAD, Restaurant etwa 10 %, Taxi aufrunden um 5 bis 10 MAD, Fahrer f\xfcr einen ganzen Tag 100 bis 150 MAD.'],links:[{label:'Ausw\xe4rtiges Amt: Marokko',url:n},{label:'Regionalportal Agadir Souss-Massa',url:'https://explore-agadirsoussmassa.com/en/?p=34972'}]},{id:'trips',title:'Ausfl\xfcge au\xdfer Surfen',icon:'map-marker-path',items:['Paradise Valley: Palmenschlucht mit nat\xfcrlichen Becken im Hinterland von Tamraght und Taghazout. Vom Parkplatz etwa 30 Minuten zu Fu\xdf, Entfernung je nach Quelle 17 bis 35 km [ungenau].','Quad und Buggy: gef\xfchrte Touren von 1 bis 1,5 Stunden zwischen Taghazout und Tamraght (Anbieter-Angebote). Vorher kl\xe4ren, ob die Reiseversicherung das abdeckt [nicht belegt]. Das Ausw\xe4rtige Amt r\xe4t zu einer Versicherung mit R\xfccktransport.','Paddeln (SUP): In Imsouane werden SUP und Windsurfen angeboten (Strandportal, nicht amtlich). Ruhig ist es vor allem in der Bucht bei kleinem Swell. Meine Einsch\xe4tzung, keine Quelle.','Nationalpark Souss-Massa: Zwischen Agadir und Sidi Ifni, mit Besucherzentrum am Oued Massa und etwa 250 Vogelarten, darunter Kolonien des seltenen Waldrapps.','Essaouira: Die Medina ist UNESCO-Welterbe, rund 175 km n\xf6rdlich von Agadir.','Agadir Oufella: Ruine der Kasbah von 1572 \xfcber der Stadt, beim Erdbeben 1960 zerst\xf6rt. Seit 2022 f\xe4hrt eine Seilbahn hinauf.'],links:[{label:'Wikipedia: Souss-Massa (englisch)',url:'https://en.wikipedia.org/wiki/Souss-Massa_National_Park'},{label:'Wikipedia: Essaouira (englisch)',url:'https://en.wikipedia.org/wiki/Essaouira'},{label:'Wikipedia: Agadir (englisch)',url:'https://en.wikipedia.org/wiki/Agadir'},{label:'Regionalportal: Paradise Valley',url:'https://explore-agadirsoussmassa.com/en/?p=34716'}]},{id:'safety',title:'Sicherheit und Regeln',icon:'shield-alert-outline',items:['Diebstahl: Mopedfahrer rei\xdfen offen getragene Taschen und Handys weg, besonders in Medinas. Kein Widerstand, Vorf\xe4lle der Polizei melden. Nur Tagesbargeld dabeihaben.','Strand und Auto: amtlich [\u2026] nicht belegt. Meine Empfehlung (keine Quelle): nichts sichtbar im Auto lassen, Wertsachen nicht mit ans Wasser nehmen.','Alkohol: Kauf nur in bestimmten Gesch\xe4ften, Ausschank in zugelassenen Lokalen. Trinken auf der Stra\xdfe oder am Strand ist verboten und kann zur Verhaftung f\xfchren.','Drogen: schon kleinste Mengen sind strafbar, bis zu zehn Jahre Haft. Kein Gep\xe4ck von Dritten annehmen.','Paare: Hotels k\xf6nnen eine Heiratsurkunde verlangen, au\xdfereheliche Beziehungen sind strafbar. \xd6ffentliche Zur\xfcckhaltung.','Anmeldung in Unterk\xfcnften: [\u2026] nicht belegt. Den Gastgeber vorher fragen, ob er Passdaten braucht.','Notrufe: Polizei 19, Gendarmerie 177 (au\xdferhalb der St\xe4dte), Rettung 15. Kartensperre +49 116 116.'],links:[{label:'Ausw\xe4rtiges Amt: Marokko',url:n}]},{id:'surf',title:'Surfen vor Ort',icon:'surfing',items:['Neopren im November: Wasser bis etwa 21 \xb0C (Wikipedia, unbelegt). Dicke [\u2026]. Meine Annahme: eher 3/2 mm, dazu Wax, Leash und Reparaturset.','Boardtransport im Flug: Boardbag-Regeln und Geb\xfchr bei der Airline kl\xe4ren [\u2026].','Etikette im Line-up und Localism: [\u2026] nicht belegt. Allgemeine Regeln: wer am tiefsten sitzt hat Vorfahrt, nicht droppen, Respekt vor Locals.','Imsouane: \u201eLa Bay\u201c ist ein Pointbreak, geeignet f\xfcr Anf\xe4nger und Longboards. \u201eLa Cath\xe9drale\u201c ist ein Beachbreak.','Strand: Das Ausw\xe4rtige Amt warnt vor punktuellen Abwassereinleitungen. Str\xe4nde mit Tieren meiden.','Unfall: 15 oder 19 rufen, zur n\xe4chsten Klinik fahren, die Versicherung fr\xfch informieren.'],links:[{label:'Wikipedia: Imsouane',url:'https://en.wikipedia.org/wiki/Imsouane'},{label:'Ausw\xe4rtiges Amt: Marokko',url:n}]}]},958,[]);